from pathlib import Path
from lxml import html as LH
import re,html,json

def p(*texts):return ''.join('<p>'+s+'</p>' for s in texts)
def ul(*texts):return '<ul>'+''.join('<li>'+s+'</li>' for s in texts)+'</ul>'
def link(slug,label):return '<a href="'+slug+'.html">'+label+'</a>'
DATA={
'lai-xe-ho-o-to-da-nang':{
'intro':'Cần người lái thay để đưa bạn và ô tô về nhà sau buổi tiệc, hoặc hỗ trợ một lịch trình bận rộn? Như Ý Driver cung cấp dịch vụ lái hộ ô tô tại Đà Nẵng bằng chính xe của bạn, với lộ trình và chi phí được thống nhất trước chuyến.',
'desc':'Lái hộ ô tô tại Đà Nẵng bằng xe của khách. Xem giá từ 150.000đ cho 0–5 km, quy trình đặt, bàn giao xe và liên hệ Như Ý Driver: 0985 666 044.',
'sections':[
('Lái hộ ô tô: bạn và chiếc xe cùng đến nơi',p('Bạn đã mang ô tô đến buổi hẹn nhưng không muốn tự điều khiển lúc về? Với dịch vụ lái hộ, tài xế đến điểm đón và lái chính chiếc xe đó theo hành trình hai bên đã xác nhận. Bạn không phải bố trí thêm một lượt quay lại lấy xe nếu xe được đưa về cùng chuyến.','Đây là dịch vụ thuê người lái thay trên ô tô của khách. Khi liên hệ, bạn nên nói rõ dòng xe, hộp số, số người đi cùng và nơi xe đang đỗ để Như Ý Driver trao đổi người lái phù hợp.')),
('Những lúc bạn có thể cần tài xế lái hộ ô tô',ul('<strong>Sau tiệc, liên hoan:</strong> sắp xếp đường về cho cả người và xe khi không tự lái.','<strong>Khi mệt hoặc thiếu tập trung:</strong> nghỉ ngơi và tìm người hỗ trợ thay vì cố hoàn thành hành trình.','<strong>Lịch làm việc nhiều điểm:</strong> cần người lái trong một buổi họp, gặp khách hoặc xử lý việc cá nhân.','<strong>Đưa đón người thân:</strong> chủ động dùng xe gia đình với lịch trình đã trao đổi.','<strong>Đi xa bằng xe riêng:</strong> gửi kế hoạch để hỏi '+link('thue-tai-xe-di-tinh-da-nang','tài xế đi tỉnh')+' và thời gian phục vụ.')),
('Bảng giá lái hộ ô tô tại Đà Nẵng','<table><caption>Giá tham khảo dịch vụ lái hộ ô tô Như Ý Driver</caption><thead><tr><th scope="col">Quãng đường / thời gian</th><th scope="col">Mức phí</th></tr></thead><tbody><tr><th scope="row">0–5 km</th><td>150.000đ</td></tr><tr><th scope="row">5–10 km</th><td>200.000đ</td></tr><tr><th scope="row">Trên 10 đến 30 km</th><td>200.000đ + 15.000đ/km vượt 10 km</td></tr><tr><th scope="row">Trên 30 km</th><td>Liên hệ báo giá</td></tr><tr><th scope="row">23:00–05:59</th><td>Cộng 50.000đ</td></tr></tbody></table>'+p('Giá thực tế được xác nhận trước chuyến đi. Khi cần chờ lâu, ghé thêm điểm hoặc thuê nhiều giờ, hãy gửi đầy đủ lịch trình để được báo tổng chi phí. Xem '+link('bang-gia-lai-xe-ho-da-nang','bảng giá chi tiết')+' nếu cần đối chiếu thêm ô tô và xe máy.')),
('Thuận tiện khi vẫn muốn dùng xe riêng',p('Xe ở ngay nhà khi chuyến đi kết thúc là một thuận tiện rõ ràng nếu sáng hôm sau bạn còn cần đi làm, đưa đón gia đình hoặc tiếp tục công việc. Bạn cũng có thể giữ lịch trình bằng chiếc xe quen thuộc, thay vì chuyển đồ sang phương tiện khác.','Điều nên làm là trao đổi rõ từ đầu: điểm đón, điểm trả, các chặng dừng và thời gian dự kiến. Khi những thông tin này đầy đủ, bạn dễ xem báo giá có đúng nhu cầu và chuẩn bị bàn giao hơn.')),
('Đón xe ở đâu tại Đà Nẵng?',p('Bạn có thể gửi yêu cầu đón tại nhà hàng, khách sạn, nhà riêng hoặc bãi đỗ ở các khu vực '+link('khu-vuc-phuc-vu','Như Ý Driver phục vụ tại Đà Nẵng')+'. Với xe ở hầm, nhớ gửi cổng vào, tầng và vị trí đỗ; với điểm đón có nhiều lối, thêm một mốc dễ nhận biết.','Khả năng bố trí và thời gian đón được kiểm tra theo vị trí và lịch tài xế. Hãy giữ điện thoại liên lạc được để nhận thông tin xác nhận.')),
('Trước khi bàn giao ô tô',ul('Đối chiếu thông tin người nhận xe với điều phối.','Kiểm tra tình trạng xe, nhiên liệu và những lưu ý đã biết.','Giới thiệu thao tác riêng: phanh tay, cần số, khóa thông minh, thẻ ra vào.','Thống nhất các điểm ghé, nơi đỗ cuối chuyến và khoản chờ nếu có.')+p('Bạn có thể xem '+link('can-chuan-bi-gi-khi-ban-giao-xe','danh sách bàn giao xe')+' để chuẩn bị gọn trước khi gặp tài xế.'))],
'faq':[('Dịch vụ có đưa một chiếc ô tô khác đến không?','Lái hộ ô tô sử dụng xe của khách. Nếu bạn cần cả phương tiện đưa đón, hãy nói rõ nhu cầu khi liên hệ.'),('Xe số sàn và số tự động có cần báo riêng không?','Có. Bạn nên nêu dòng xe và kiểu hộp số để điều phối trao đổi khả năng bố trí người lái.'),('Tôi muốn ghé thêm một địa chỉ thì sao?','Gửi điểm ghé khi hỏi giá. Nếu phát sinh sau đó, báo lại để thống nhất lộ trình và chi phí trước khi đi.')],
'related':['bang-gia-lai-xe-ho-da-nang','lai-xe-ho-sau-tiec-da-nang','can-chuan-bi-gi-khi-ban-giao-xe']},
'lai-xe-ho-sau-tiec-da-nang':{
'intro':'Cuộc vui kết thúc, bạn vẫn có thể đưa cả mình và xe về nhà mà không tự cầm lái. Như Ý Driver nhận lái hộ sau tiệc tại Đà Nẵng; bạn gửi vị trí, loại xe và giờ về để được tư vấn, xác nhận chuyến.',
'desc':'Lái xe hộ sau tiệc tại Đà Nẵng: tài xế đến nhận và lái chính xe của khách. Xem cách đặt, giá tham khảo, điểm đón và lưu ý bàn giao xe.',
'sections':[
('Sau buổi tiệc, ai sẽ đưa xe của bạn về?',p('Bạn đi ô tô hoặc xe máy đến buổi liên hoan, tiệc cưới hay cuộc gặp bạn bè. Đến lúc ra về, điều cần giải quyết không chỉ là một chỗ ngồi về nhà mà còn là chiếc xe đang ở bãi. Lái xe hộ là phương án để bạn cân nhắc khi muốn đưa xe về cùng.','Tài xế đến nơi đã hẹn, nhận xe sau khi đối chiếu thông tin rồi lái chính phương tiện của khách đến điểm trả. Với từng loại xe và số người đi cùng, cách bố trí chuyến cần được trao đổi ngay khi đặt.')),
('Lợi ích khi chủ động đặt người lái thay',ul('<strong>Đưa xe về cùng:</strong> thuận tiện nếu bạn còn cần dùng phương tiện vào sáng hôm sau.','<strong>Chủ động trước khi ra về:</strong> có thời gian hỏi giá và chờ xác nhận tại địa điểm đang ngồi.','<strong>Rõ điểm đón, điểm trả:</strong> thống nhất trước cả những chặng ghé dọc đường.','<strong>Biết chi phí trước chuyến:</strong> trao đổi tổng phí theo loại xe, hành trình và giờ đi.')),
('Chọn đúng dịch vụ cho ô tô hoặc xe máy',p('Nếu đi ô tô, báo dòng xe, hộp số và số người về cùng. Nếu có nhiều điểm trả khách, gửi đủ địa chỉ và thứ tự dự kiến. '+link('lai-xe-ho-o-to-da-nang','Thông tin lái hộ ô tô')+' giúp bạn xem trước quy trình và mức giá theo quãng đường.','Nếu đi xe máy, nói rõ xe số, xe tay ga hay xe côn tay cùng số người cần di chuyển. Nếu người đi cùng không thể ngồi vững, hãy nhờ người thân hỗ trợ và trao đổi phương tiện khác phù hợp. Xem '+link('lai-xe-ho-xe-may-da-nang','dịch vụ lái hộ xe máy')+' để chuẩn bị đúng nhu cầu.')),
('Giá lái xe hộ sau tiệc tính theo gì?',p('Chi phí phụ thuộc loại phương tiện, quãng đường và giờ khởi hành. Ô tô có mức tham khảo 150.000đ cho 0–5 km và 200.000đ cho 5–10 km; xe máy có bảng giá riêng. Giá thực tế được xác nhận trước chuyến đi.','Bạn có thể xem '+link('bang-gia-lai-xe-ho-da-nang','bảng giá ô tô và xe máy')+'. Nếu tiệc kết thúc muộn, cần chờ hoặc muốn ghé thêm địa chỉ, nói rõ khi hỏi giá để nhận thông tin cho toàn bộ chuyến.')),
('Đón tại nhà hàng hoặc bãi xe thế nào cho dễ tìm?',p('Gửi ghim vị trí kèm tên địa điểm và chỗ xe đang đỗ. Với nhà hàng có nhiều cổng, cho biết cổng bạn sẽ ra; với ô tô trong hầm, thêm tầng và số ô đỗ. Một địa chỉ chung có thể chưa đủ để tài xế gặp đúng người.','Chờ tại nơi sáng, dễ nhận biết và giữ điện thoại còn pin. Nếu giờ về thay đổi, báo sớm qua đầu mối đã đặt thay vì tự đổi điểm gặp trong lúc tài xế đang đến.')),
('Kiểm tra người nhận xe trước khi giao chìa khóa',p('Đối chiếu thông tin tài xế với điều phối, thống nhất điểm đến và giới thiệu thao tác riêng của phương tiện. Cuối chuyến, nhận lại chìa khóa, kiểm tra đồ cá nhân và hoàn tất thanh toán theo nội dung đã thống nhất.','Để chủ động hơn, bạn có thể lưu '+link('huong-dan-dat-tai-xe-nhu-y-driver','mẫu tin nhắn đặt tài xế qua Zalo')+' và '+link('dat-tai-xe-lai-ho-ban-dem-da-nang','kinh nghiệm đặt chuyến ban đêm')+' trước buổi hẹn.'))],
'faq':[('Nên gọi từ lúc nào?', 'Bạn có thể liên hệ khi đã có giờ về dự kiến, thay vì đợi đến lúc đứng ở bãi xe. Thời gian đón sẽ được trao đổi theo lịch thực tế.'),('Nhờ tài xế trả nhiều người ở nhiều địa chỉ được không?','Hãy gửi đầy đủ các điểm dừng để điều phối kiểm tra hành trình và báo giá trước.'),('Nếu muốn gửi xe lại và đi phương tiện khác thì sao?','Hỏi địa điểm về việc giữ xe, giờ nhận lại và chi phí. Bạn có thể cân nhắc phương án phù hợp với lịch hôm sau.')],
'related':['di-tiec-bang-o-to-da-nang','uong-ruou-bia-mang-theo-xe-may','bang-gia-lai-xe-ho-da-nang']},
'lai-xe-ho-xe-may-da-nang':{
'intro':'Bạn có xe máy tại điểm hẹn nhưng không thể tự lái về? Như Ý Driver nhận yêu cầu lái hộ xe máy tại Đà Nẵng. Gửi vị trí, loại xe và số người để trao đổi cách đưa người và xe về phù hợp.',
'desc':'Dịch vụ lái hộ xe máy tại Đà Nẵng: xe số, tay ga, yêu cầu người đi cùng, bảng giá và quy trình đặt tài xế Như Ý Driver. Gọi 0985 666 044.',
'sections':[
('Lái hộ xe máy là dịch vụ gì?',p('Lái hộ xe máy là hình thức nhờ tài xế điều khiển chính chiếc xe của bạn theo hành trình đã thỏa thuận. Dịch vụ phù hợp khi xe đã có ở điểm đón và bạn cần người lái thay, chẳng hạn sau buổi liên hoan hoặc khi không muốn tự điều khiển.','Ngay lúc liên hệ, bạn nên báo xe số, tay ga hay côn tay, số người cần về và địa chỉ trả. Cách bố trí người và xe được trao đổi trước khi nhận chuyến, thay vì mặc định mọi yêu cầu đều giống nhau.')),
('Khi nào nên cân nhắc lái hộ xe máy?',ul('Sau buổi tiệc, bạn muốn đưa xe về cùng mà không tự lái.','Bạn không muốn để xe lại qua đêm vì sáng hôm sau còn cần sử dụng.','Bạn muốn nhờ người lái cho một hành trình đã có sẵn xe ở điểm hẹn.','Bạn đang cân nhắc giữa '+link('uong-ruou-bia-mang-theo-xe-may','lái hộ và gửi xe lại sau tiệc')+'.')),
('Giá lái hộ xe máy tại Đà Nẵng',p('Xe máy có biểu phí riêng: 0–5 km là 110.000đ, 5–7 km là 130.000đ và 7–10 km là 170.000đ. Trên 10 km có phần phí theo km; chuyến qua 23 giờ có phụ phí giờ khuya. Bạn nên xem '+link('bang-gia-lai-xe-ho-da-nang','bảng giá xe máy')+' và hỏi tổng phí theo địa chỉ thực tế.','Khi đặt, hãy nói rõ đây là xe máy để được tư vấn đúng biểu phí. Giá thực tế được xác nhận trước chuyến đi; nếu có chờ, ghé thêm điểm hoặc thay đổi giờ, cần trao đổi lại trước khi khởi hành.')),
('Thuận tiện khi cần cả người và xe về cùng',p('Việc đưa xe về cùng giúp bạn bớt một lần quay lại lấy và chủ động sử dụng vào hôm sau. Điều này hữu ích nếu địa điểm không nhận giữ xe qua đêm hoặc giờ mở bãi không khớp kế hoạch của bạn.','Tuy nhiên, cần xem cả tình trạng của người đi cùng. Nếu bạn hoặc người đi cùng không thể ngồi vững trên xe, hãy nhờ người thân hỗ trợ và chọn phương án di chuyển phù hợp. Đừng chỉ giải quyết chiếc xe mà bỏ qua nhu cầu của người.')),
('Chuẩn bị trước khi tài xế đến',ul('Gửi ghim vị trí, tên địa điểm và cổng hoặc bãi nhận xe.','Chuẩn bị chìa khóa, vé gửi xe và mũ bảo hiểm phù hợp.','Báo đúng loại xe và số người cần di chuyển.','Thống nhất điểm đến, giờ đi và tổng phí.','Đối chiếu thông tin tài xế trước khi bàn giao.')),
('Nếu chọn gửi xe lại thay vì lái hộ',p('Bạn cần hỏi địa điểm về quyền gửi qua đêm, giờ lấy xe, phí giữ và giấy tờ nhận xe. Khi so sánh chi phí, tính cả lượt đi về nhà lẫn lượt quay lại bãi hôm sau.','Nếu muốn kiểm tra chuyến lái hộ, gọi <a href="tel:0985666044">0985 666 044</a> hoặc nhắn Zalo Như Ý Driver với loại xe, địa chỉ đón và điểm đến.'))],
'faq':[('Xe máy có dùng giá ô tô không?','Không. Xe máy có bảng giá riêng; hãy nêu rõ loại phương tiện khi liên hệ.'),('Có hai người cần về thì báo thế nào?','Bạn cần báo đầy đủ số người, số xe và tình trạng người đi cùng để trao đổi cách bố trí trước chuyến.'),('Xe côn tay có cần nói trước không?','Có. Nên báo loại xe và những thao tác riêng từ lúc đặt để kiểm tra người lái phù hợp.')],
'related':['uong-ruou-bia-mang-theo-xe-may','bang-gia-lai-xe-ho-da-nang','can-chuan-bi-gi-khi-ban-giao-xe']},
'thue-tai-xe-theo-gio-da-nang':{
'intro':'Một buổi có nhiều cuộc hẹn sẽ thuận tiện hơn khi bạn có người lái thay và vẫn dùng xe riêng. Gửi giờ bắt đầu, các điểm ghé và giờ kết thúc để Như Ý Driver tư vấn thuê tài xế theo giờ tại Đà Nẵng.',
'desc':'Thuê tài xế theo giờ tại Đà Nẵng cho lịch họp, việc cá nhân và nhiều điểm dừng bằng xe riêng. Xem cách tính thời gian, yêu cầu báo giá và đặt lịch.',
'sections':[
('Thuê tài xế theo giờ phù hợp với lịch trình nào?',p('Bạn cần ghé ngân hàng, tới văn phòng rồi đi một cuộc hẹn trong cùng buổi chiều. Nếu muốn có người lái xuyên suốt khoảng thời gian đó, hãy gửi lịch trình để hỏi phương án theo giờ thay vì đặt riêng từng lượt.','Tài xế điều khiển xe của khách theo lịch đã thống nhất. Bạn cần chuẩn bị phương tiện, nêu rõ dòng xe và giờ sử dụng; các điều kiện phục vụ được trao đổi trước khi chốt.')),
('Lợi ích khi các điểm hẹn nằm trong cùng một lịch',ul('<strong>Giữ xe riêng trong suốt hành trình:</strong> đồ dùng và phương tiện có thể đi cùng theo nhu cầu.','<strong>Chủ động các điểm ghé:</strong> gửi toàn bộ chặng đi để điều phối nắm lịch.','<strong>Có thời gian cho công việc:</strong> bạn tập trung vào các cuộc hẹn khi đã có người lái thay.','<strong>Dễ so sánh chi phí:</strong> xem tổng giá cho một khoảng sử dụng và các khoản ngoài phạm vi.')),
('Thời gian chờ cũng là phần cần tính',p('Thuê theo giờ không chỉ gồm thời gian bánh xe lăn. Nếu tài xế chờ trong lúc bạn làm việc, đón người hoặc tham dự cuộc hẹn, khoảng chờ đó cần có trong lịch dự kiến. Đây là thông tin quan trọng để hỏi giá và chọn thời lượng phù hợp.','Bạn nên trao đổi giờ bắt đầu tính, số giờ tối thiểu, cách làm tròn và mức tính nếu kết thúc muộn. Trường hợp lịch còn kéo dài tới tối, có thể so sánh thêm '+link('thue-tai-xe-theo-ngay-da-nang','phương án thuê theo ngày')+'.')),
('Chi phí thuê theo giờ được báo thế nào?',p('Gửi cùng lúc loại xe, thời lượng, các điểm đi và thời gian chờ. Như Ý Driver sẽ kiểm tra lịch tài xế và tư vấn chi phí theo yêu cầu cụ thể. Bạn nên hỏi tổng phí dự kiến thay vì chỉ một đơn giá tách khỏi lịch trình.','Trước khi đồng ý, làm rõ khoản nào đã bao gồm, cách tính vượt giờ và các phí cầu đường, đỗ xe nếu có. Giá theo km của chuyến đơn lẻ không mặc định là giá cho một lịch thuê nhiều giờ.')),
('Ví dụ thông tin bạn có thể gửi',p('“Mình cần tài xế lái ô tô từ 13:30 đến khoảng 17:30. Đón tại [địa chỉ], ghé [điểm 1] chờ khoảng [thời gian], rồi đến [điểm 2] và kết thúc ở [địa chỉ]. Xe [dòng xe, hộp số]. Nhờ báo tổng phí và cách tính nếu về muộn.”','Thay các phần trong ngoặc bằng lịch thực tế. Nếu kế hoạch chưa chắc, nêu khoảng giờ và những điểm có thể đổi để được tư vấn ngay từ đầu.')),
('Khi lịch thay đổi trong ngày',p('Nếu cuộc hẹn kéo dài hoặc bạn muốn thêm điểm dừng, báo sớm cho điều phối và tài xế để kiểm tra thời gian phục vụ. Không nên mặc định tài xế luôn có thể ở lại sau giờ đã hẹn.','Xem '+link('thue-tai-xe-theo-gio-hay-theo-ngay','so sánh thuê theo giờ và theo ngày')+' nếu bạn đang cân nhắc giữa hai cách đặt. Hotline/Zalo Như Ý Driver: <a href="tel:0985666044">0985 666 044</a>.'))],
'faq':[('Chỉ có một lượt đi thì có cần thuê theo giờ không?','Bạn có thể hỏi giá theo chuyến để so sánh. Gửi đúng điểm đi, điểm đến và nhu cầu chờ để được tư vấn.'),('Có được tự thay đổi lịch trình không?','Hãy trao đổi trước khi thay đổi để thống nhất khả năng phục vụ, giờ kết thúc và chi phí.'),('Thuê theo giờ có bao gồm xe không?','Thông tin trên trang này dành cho người cần tài xế lái xe của khách. Nếu cần thêm phương tiện, nói rõ ngay khi hỏi dịch vụ.')],
'related':['thue-tai-xe-theo-gio-hay-theo-ngay','thue-tai-xe-theo-ngay-da-nang','huong-dan-dat-tai-xe-nhu-y-driver']},
'thue-tai-xe-theo-ngay-da-nang':{
'intro':'Lịch công tác, gặp khách hoặc di chuyển cùng gia đình kéo dài cả ngày? Bạn có thể gửi kế hoạch cho Như Ý Driver để kiểm tra lịch tài xế, trao đổi thời lượng phục vụ và nhận báo giá theo nhu cầu.',
'desc':'Tư vấn thuê tài xế theo ngày tại Đà Nẵng bằng xe riêng: lịch công tác, nhiều điểm đón trả, thời lượng, khoản ngoài gói và thông tin để nhận báo giá.',
'sections':[
('Lên kế hoạch cho một ngày có nhiều chặng',p('Một ngày cần đi nhiều nơi thường có cả thời gian di chuyển và những khoảng chờ giữa các cuộc hẹn. Nếu muốn nhờ người lái xe riêng trong suốt lịch đó, bạn nên gửi kế hoạch chung để hỏi phương án theo ngày.','Như Ý Driver kiểm tra khả năng bố trí theo ngày sử dụng, loại xe và hành trình. Bạn cần thống nhất rõ phạm vi công việc trước khi xác nhận, đặc biệt khi giờ kết thúc có thể thay đổi.')),
('Những nhu cầu có thể gửi để được tư vấn',ul('Lịch công tác trong ngày với nhiều cuộc hẹn.','Di chuyển bằng xe gia đình qua nhiều điểm đón, trả.','Lịch tham quan hoặc thăm người thân có thời gian chờ.','Một ngày cần người lái thay để bạn tập trung vào công việc.','Hành trình có lượt đi và lượt về cần sắp xếp chung.')),
('Thuận tiện ở việc trao đổi cả lịch trình từ đầu',p('Gửi một kế hoạch chung giúp bạn và điều phối nhìn được tổng thời lượng, các điểm dừng và những mốc phải có mặt. Bạn cũng dễ hỏi báo giá cho toàn bộ ngày sử dụng, thay vì ghép nhiều chuyến mà chưa tính hết thời gian chờ.','Với gia đình hoặc nhóm công việc, nên chỉ định một đầu mối liên lạc để cập nhật lịch. Nếu có nhiều người lên xuống ở các điểm khác nhau, báo trước số người và địa chỉ từng chặng.')),
('Gói theo ngày bao gồm bao nhiêu giờ?',p('Bạn cần hỏi số giờ phục vụ được bao gồm và giờ bắt đầu, kết thúc cụ thể. Không nên tự hiểu “theo ngày” là người lái luôn ở lại đủ 24 giờ hoặc có thể chạy thêm mọi chặng ngoài kế hoạch.','Những mục cần làm rõ gồm quãng đường, thời gian chờ, nghỉ, phí vượt giờ, cầu đường, đỗ xe và các khoản liên quan nếu có. Nội dung nào đã được tính trong giá nên được ghi rõ khi chốt lịch.')),
('Cách yêu cầu báo giá sát nhu cầu',p('Gửi ngày đi, địa chỉ đón, giờ bắt đầu và giờ dự kiến kết thúc. Kèm danh sách điểm ghé, thời gian chờ ở mỗi nơi, loại xe và phương án một chiều hay quay về. Nếu còn điểm chưa chắc, ghi rõ để điều phối biết phần có thể thay đổi.','Bạn có thể đề nghị so sánh thêm '+link('thue-tai-xe-theo-gio-da-nang','giá theo giờ')+' cho cùng kế hoạch. Cách so sánh hữu ích là tổng phí và phạm vi sử dụng, thay vì tên gói hoặc một mức giá đứng riêng.')),
('Nếu có thêm lịch đi tỉnh hoặc qua đêm',p('Hãy báo ngay từ lúc đặt nếu chuyến ra ngoài Đà Nẵng, kéo dài qua đêm hoặc cần tài xế chờ ở điểm đến. Những yếu tố này ảnh hưởng việc sắp xếp người lái và các điều kiện phục vụ. Xem '+link('thue-tai-xe-di-tinh-da-nang','hướng dẫn thuê tài xế đi tỉnh')+' để chuẩn bị kế hoạch.','Liên hệ <a href="tel:0985666044">0985 666 044</a> hoặc Zalo Như Ý Driver. Lịch tài xế và tổng giá được xác nhận trước khi bạn chốt yêu cầu.'))],
'faq':[('Gói ngày có luôn bao gồm mọi quãng đường không?','Không nên mặc định. Hãy hỏi phạm vi hành trình, giới hạn nếu có và cách tính khi thêm tuyến.'),('Đặt lịch trước nhưng chưa biết đủ điểm ghé thì sao?','Gửi kế hoạch hiện có cùng những điểm còn có thể thay đổi, rồi thống nhất cách cập nhật trước ngày đi.'),('Kết thúc sớm hoặc muộn hơn dự kiến thì tính thế nào?','Điều kiện thay đổi thời lượng cần được trao đổi trong báo giá trước khi đặt.')],
'related':['thue-tai-xe-theo-gio-hay-theo-ngay','thue-tai-xe-di-tinh-da-nang','huong-dan-dat-tai-xe-nhu-y-driver']},
'thue-tai-xe-di-tinh-da-nang':{
'intro':'Muốn đi xa bằng xe riêng nhưng cần người lái thay? Gửi hành trình xuất phát từ Đà Nẵng để Như Ý Driver kiểm tra lịch tài xế, trao đổi lượt đi, lượt về và báo chi phí cho chuyến của bạn.',
'desc':'Thuê tài xế đi tỉnh từ Đà Nẵng bằng xe riêng: cách gửi hành trình, báo giá một chiều hoặc khứ hồi, thời gian chờ và chuẩn bị cho chuyến dài.',
'sections':[
('Đi tỉnh bằng xe riêng, thuê người lái thay',p('Khi đi công việc, thăm người thân hoặc có một hành trình dài, bạn có thể muốn nghỉ ngơi trên xe thay vì tự điều khiển suốt quãng đường. Thuê người lái thay là phương án để cân nhắc nếu đã có phương tiện và kế hoạch di chuyển.','Như Ý Driver kiểm tra yêu cầu theo tuyến, ngày đi, loại xe và thời lượng phục vụ. Gửi đầy đủ thông tin từ đầu sẽ giúp hai bên trao đổi chi phí và chuẩn bị lịch người lái phù hợp hơn.')),
('Những thông tin quyết định cách sắp xếp chuyến',ul('<strong>Điểm xuất phát và điểm đến:</strong> gửi địa chỉ cụ thể, không chỉ tên tỉnh hoặc thành phố.','<strong>Ngày, giờ đi:</strong> kèm giờ cần có mặt ở điểm đến nếu có cuộc hẹn.','<strong>Một chiều hay khứ hồi:</strong> nêu lượt về trong ngày hay ngày khác.','<strong>Thời gian chờ:</strong> tài xế có ở lại điểm đến trong lúc bạn làm việc không?','<strong>Loại xe:</strong> dòng xe, hộp số, số người đi cùng và những lưu ý riêng.')),
('Thuận tiện khi giữ lịch trình với xe của mình',p('Bạn có thể mang theo đồ dùng và sử dụng chiếc xe quen thuộc trong chuyến đi. Khi có người lái thay, bạn có thời gian nghỉ hoặc dành sự chú ý cho người thân đi cùng trong phạm vi phù hợp với hành trình.','Với lịch có nhiều điểm ghé, việc trao đổi trước giúp bạn nhận một phương án tổng thể cho cả chuyến. Nếu đang phân vân giữa theo chuyến và thời lượng, xem '+link('thue-tai-xe-theo-gio-hay-theo-ngay','cách chọn thuê tài xế theo giờ hay theo ngày')+'.')),
('Giá tài xế đi tỉnh được báo theo hành trình',p('Chuyến dài cần xem cả quãng đường, lượt về, thời gian chờ và tổng thời lượng. Bạn nên hỏi giá cho lịch trình đầy đủ, làm rõ phí cầu đường, đỗ xe, ăn nghỉ nếu có và cách xử lý khi phát sinh chặng mới.','Với quãng đường trên 30 km, vui lòng liên hệ để nhận báo giá theo yêu cầu. '+link('bang-gia-lai-xe-ho-da-nang','Bảng giá tham khảo')+' giúp bạn xem cách phân loại dịch vụ, nhưng không thay cho báo giá riêng của một lịch đi tỉnh.')),
('Hỏi tuyến cụ thể thay vì mặc định có lịch',p('Nếu dự định đi Hội An, Huế hoặc một điểm ngoài Đà Nẵng, hãy gửi đúng địa chỉ và thời gian để kiểm tra. Mỗi yêu cầu cần xem vị trí xuất phát, khả năng bố trí và kế hoạch quay về; không nên chỉ dựa vào tên tuyến để chốt chuyến.','Nếu chưa chắc giờ về, nói rõ khoảng thời gian dự kiến và mức độ linh hoạt. Khi lịch thay đổi, báo lại sớm để trao đổi thời lượng và chi phí mới.')),
('Chuẩn bị xe và bàn giao trước ngày đi',p('Kiểm tra tình trạng phương tiện, nhiên liệu và các lưu ý vận hành trước khi xuất phát. Giới thiệu thao tác riêng của xe với tài xế; cùng thống nhất thời gian nghỉ và các điểm dừng cần thiết trong chuyến.','Bạn có thể xem '+link('can-chuan-bi-gi-khi-ban-giao-xe','những việc cần chuẩn bị khi giao xe')+'. Để hỏi lịch người lái, gọi <a href="tel:0985666044">0985 666 044</a> hoặc gửi Zalo kèm hành trình.'))],
'faq':[('Đi một chiều và khứ hồi có cùng cách báo giá không?','Hai lịch trình cần thông tin khác nhau về lượt về và thời gian chờ. Hãy nêu đúng nhu cầu để nhận báo giá cho toàn chuyến.'),('Có thể thêm điểm dừng trong lúc đi không?','Trao đổi với điều phối và tài xế trước khi thay đổi, vì chặng mới có thể ảnh hưởng lịch và chi phí.'),('Đặt sớm có cần cung cấp đầy đủ loại xe không?','Có. Dòng xe, hộp số và ngày giờ đi giúp kiểm tra khả năng bố trí phù hợp.')],
'related':['thue-tai-xe-theo-ngay-da-nang','can-chuan-bi-gi-khi-ban-giao-xe','huong-dan-dat-tai-xe-nhu-y-driver']}
}

for slug,data in DATA.items():
 path=Path(slug+'.html');s=path.read_text(encoding='utf-8')
 s=re.sub(r'<p class="lead">.*?</p>',lambda m:'<p class="lead">'+data['intro']+'</p>',s,count=1)
 for attr in ['name="description"','property="og:description"']:
  s=re.sub(r'(<meta '+attr+r' content=")[^"]*',lambda m:m.group(1)+html.escape(data['desc'],quote=True),s,count=1)
 start=s.index('<div class="reading">');marker=re.search(r'<section>\s*<h2>',s[start:]);body_start=start+marker.start()
 head=s[start:body_start]
 # Existing scoped tags remain; add a contents list for the longer service explanation.
 chapters=data['sections']
 toc='<nav class="toc" aria-label="Mục lục"><strong>Nội dung dịch vụ</strong><ul>'+''.join(f'<li><a href="#dich-vu-{i}">{title}</a></li>' for i,(title,_) in enumerate(chapters,1))+'<li><a href="#dat-dich-vu">Cách đặt tài xế</a></li><li><a href="#cau-hoi">Câu hỏi thường gặp</a></li></ul></nav>'
 content=''.join(f'<section><h2 id="dich-vu-{i}">{title}</h2>{body}</section>' for i,(title,body) in enumerate(chapters,1))
 content+='<section><h2 id="dat-dich-vu">Đặt tài xế Như Ý Driver như thế nào?</h2><ol><li><strong>Liên hệ:</strong> gọi <a href="tel:0985666044">0985 666 044</a>, nhắn <a href="https://zalo.me/0985666044">Zalo</a> hoặc gửi <a href="index.html#quick-booking">biểu mẫu đặt tài xế</a>.</li><li><strong>Gửi lịch trình:</strong> điểm đón, điểm đến, loại xe, giờ đi và các yêu cầu chờ hoặc ghé thêm điểm.</li><li><strong>Xác nhận chuyến:</strong> trao đổi tổng phí, thời gian đón dự kiến và thông tin người nhận xe.</li><li><strong>Bàn giao và kết thúc:</strong> kiểm tra xe, thực hiện hành trình, nhận lại chìa khóa và thanh toán theo nội dung đã thống nhất.</li></ol></section>'
 # Keep the handover illustration where it supports the after-party service.
 if slug=='lai-xe-ho-sau-tiec-da-nang':
  image=re.search(r'<img[^>]*src="assets/images/website/14_[^>]*>',s)
  if image:content+='<figure class="article-figure">'+image.group()+'<figcaption>Đối chiếu người nhận xe và bàn giao chìa khóa trước khi khởi hành.</figcaption></figure>'
 content+='<section><h2 id="cau-hoi">Câu hỏi thường gặp</h2>'+''.join('<details><summary>'+q+'</summary><p>'+answer+'</p></details>' for q,answer in data['faq'])+'</section>'
 content+='<section><h2>Thông tin liên quan</h2><div class="related">'
 for target in data['related']:
  title=LH.parse(target+'.html').xpath('//h1')[0].text_content();content+=link(target,title)
 content+='</div></section>'
 tail=s.index('<section class="contact">',body_start)
 s=s[:start]+head+toc+content+s[tail:]
 path.write_text(s,encoding='utf-8')

# Match the news previews to the updated service introductions.
path=Path('tin-tuc.html');s=path.read_text(encoding='utf-8')
def update(match):
 card=match.group();slug=re.search(r'href="([a-z0-9-]+)\.html"',card).group(1)
 if slug not in DATA:return card
 d=LH.fromstring(card);title=d.xpath('.//h3')[0].text_content();tags=d.get('data-topics') or ''
 card=re.sub(r'data-search="[^"]*"',lambda m:'data-search="'+html.escape(title+' '+DATA[slug]['intro']+' '+tags,quote=True)+'"',card,count=1)
